Here's a sample C++ program that reads a text file line by line, counts the number of occurrences of a specific word, and displays the count:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string wordToCount; // Word to count
    std::cout << "Enter the word to count: ";
    std::getline(std::cin, wordToCount); // Read user input

    std::string filePath; // Path to the text file
    std::cout << "Enter the file path: ";
    std::getline(std::cin, filePath); // Read user input

    std::ifstream file(filePath); // Open the file for reading

    if (!file.is_open()) { // Check if the file was opened successfully
        std::cerr << "Error: File not found or unable to open file." << std::endl;
        return 1;
    }

    std::string line; // Line of text
    int count = 0; // Count of occurrences

    while (std::getline(file, line)) { // Read each line in the file
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // Convert to lowercase
        size_t pos = std::string::npos; // Initialize the position to the end of the string

        while ((pos = line.find(wordToCount, pos)) != std::string::npos) { // Find all occurrences of the word
            pos += wordToCount.length(); // Move to the next character after the found word
            count++; // Increment the count
        }
    }

    file.close(); // Close the file

    std::cout << "The word \"" << wordToCount << "\" appears " << count << " times in the file." << std::endl;

    return 0;
}
```

Here's how the program works:

1. The user is prompted to enter the word to count and the path to the text file.
2. The program attempts to open the file for reading.
3. If the file is not found or unable to be opened, the program displays an error message and exits.
